//! 🧪️ Authored metadata preserves original allocations across bounded hashing and cancellation.
use super::*;
#[test]
fn original_native_checkpoint_command_delivers_one_authored_result_and_closes(){
 type Metadata=store::ArtifactNativeVcsCommand<State,Mutation>;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../⚙️engine/🌿️branch/commit.json")).unwrap();
 for cut in fixture["cuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([Some(usize::MAX),None]){
 let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};let result=semio_framework_os_store_engine_replay::prepare_report(&mut store,&mut caller,&mut decoder);crate::original_stream_abort::close_report_fixture(result,&mut caller,&mut decoder);
 let message=format!("{}{}",fixture["message"].as_str().unwrap(),fixture["suffix"].as_str().unwrap().repeat(fixture["repeat"].as_u64().unwrap()as usize));let mut donors=None;turn(&mut caller,&mut decoder,RetainedCloneGrant{maximum_copy_bytes:message.len()+512,..g},|cx|{let author=&fixture["author"];let capacity=message.len()+size_of::<store::Author>()+author["id"].as_str().unwrap().len()+author["name"].as_str().unwrap().len();let d=OriginalConstructionDemand{items:1,copy_bytes:message.len()+512,capacity_bytes:capacity,release_bytes:0,depth:1};admit_original_construction(cx,&mut donors,d,|_|Ok(((message.clone(),vec![store::Author{id:author["id"].as_str().unwrap().into(),name:author["name"].as_str().unwrap().into(),avatar:None}]),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:capacity,..Default::default()})))?;Ok(())});let(message,mut authors)=donors.take().unwrap();let mut message=Some(message);let pointer=message.as_ref().unwrap().as_ptr();let authors_pointer=authors.as_ptr();let mut request=None;turn(&mut caller,&mut decoder,g,|cx|{let d=OriginalConstructionDemand{items:1,copy_bytes:2*size_of::<store::ArtifactNativeVcsRequest>(),capacity_bytes:0,release_bytes:0,depth:1};admit_original_construction(cx,&mut request,d,|_|Ok((store::ArtifactNativeVcsRequest::CommitCheckpoint{message:message.take(),authors:std::mem::take(&mut authors)},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))?;Ok(())});let mut source=None;let birth=Metadata::capture_demands();for axis in [0,1,2,4]{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=birth.copy_bytes-1,2=>denied.maximum_capacity_bytes=birth.capacity_bytes-1,_=>denied.maximum_depth=0};turn(&mut caller,&mut decoder,denied,|cx|{assert!(!store.admit_native_vcs_command(&mut request,cx,&mut source)?);Ok(())});assert!(request.is_some());}turn(&mut caller,&mut decoder,g,|cx|{assert!(store.admit_native_vcs_command(&mut request,cx,&mut source)?);Ok(())});assert!(message.is_none()&&authors.is_empty());let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,g,|cx|{assert!(store.advance_native_vcs_command(source.as_mut().unwrap(),cx).is_err());Ok(())});
 for index in 0..262144{if cut==Some(index)||source.as_ref().unwrap().borrow_result().is_some(){break}turn(&mut caller,&mut decoder,g,|cx|store.advance_native_vcs_command(source.as_mut().unwrap(),cx));assert!(index<262143);}if cut.is_none(){assert!(source.as_ref().unwrap().borrow_result().is_some());let mut result=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(store.take_native_vcs_result(source.as_mut().unwrap(),cx,&mut result)?);Ok(())});assert_eq!(result.unwrap().kind,store::ArtifactNativeVcsKind::CommitCheckpoint);turn(&mut caller,&mut decoder,g,|cx|{assert!(store.ack_native_vcs_command(source.as_mut().unwrap(),cx)?);Ok(())});let parts=store.parts_ref();let checkpoint=parts.log.envelope.vcs.checkpoints.get(0).unwrap();let change=parts.log.envelope.vcs.changes.get(0).unwrap();assert_eq!(checkpoint.message.as_ref().unwrap().as_ptr(),pointer);assert_eq!(checkpoint.authors.as_ptr(),authors_pointer);assert_eq!(change.description,checkpoint.message);assert_eq!(parts.log.current_checkpoint_id.as_deref(),Some(checkpoint.id.as_str()));assert_eq!(parts.log.envelope.cursor.as_ref().unwrap().checkpoint_id,Some(checkpoint.id.clone()));assert_eq!(parts.log.envelope.transitions.len(),1);assert_eq!(parts.wire.original_outbox.len(),1);assert_eq!(store.snapshot().unwrap().zoom,1.25);}else{caller.cancel().cancel_now();}
 for index in 0..262144{if source.as_ref().unwrap().terminal_is_empty(){break}let d=store.native_vcs_command_close_demands(source.as_ref().unwrap(),4096).unwrap();let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in 0..5{let mut denied=exact;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};turn(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|{assert!(!store.close_native_vcs_command(source.as_mut().unwrap(),cx)?);Ok(())}));assert_eq!(store.native_vcs_command_close_demands(source.as_ref().unwrap(),4096).unwrap(),d);}turn(&mut caller,&mut decoder,exact,|cx|cx.with_original_retirement(|cx|store.close_native_vcs_command(source.as_mut().unwrap(),cx)));assert!(index<262143);}
 drop(source.take());for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }
}
